<template><div class="page"><div class="page-header"><div><h1 class="page-title">课程管理</h1><p class="page-description">课程是知识库、题库与试卷的组织单位。</p></div><el-button type="primary" @click="router.push('/courses/create')"><Plus/>新建课程</el-button></div><div class="toolbar card card-body"><el-input v-model="filters.keyword" placeholder="搜索课程名称" clearable style="width:260px" @keyup.enter="load"><template #prefix><Search/></template></el-input><el-select v-model="filters.status" placeholder="全部状态" clearable style="width:140px"><el-option label="使用中" value="ACTIVE"/><el-option label="已归档" value="ARCHIVED"/></el-select><el-button @click="load">查询</el-button></div><PageState :loading="loading" :error="error" :empty="!items.length" empty-text="还没有课程，先创建第一门课程。" @retry="load"><template #action><el-button type="primary" @click="router.push('/courses/create')">新建课程</el-button></template><div class="course-grid"><article v-for="c in items" :key="c.id" class="course-card card"><div class="cover"><img v-if="c.cover_url" :src="c.cover_url" alt="课程封面"><Reading v-else/></div><div class="course-content"><div class="course-head"><h3>{{c.name}}</h3><StatusTag :value="c.status"/></div><p>{{c.description||'暂无课程简介'}}</p><div class="stats"><span>文件 <b>{{c.statistics.files}}</b></span><span>章节 <b>{{c.statistics.chapters}}</b></span><span>知识点 <b>{{c.statistics.knowledge_points}}</b></span><span>题目 <b>{{c.statistics.questions}}</b></span><span>试卷 <b>{{c.statistics.papers}}</b></span></div><div class="actions"><el-button @click="router.push(`/courses/${c.id}`)">查看详情</el-button><el-button @click="edit(c)">编辑</el-button><el-button type="danger" plain @click="remove(c)">删除</el-button></div></div></article></div><el-pagination v-if="total>pageSize" v-model:current-page="page" :page-size="pageSize" :total="total" layout="prev,pager,next,total" @current-change="load"/></PageState><CourseDialog v-model="dialog" :course="editing" @saved="load"/></div></template>
<script setup>import{ref,reactive,onMounted}from'vue';import{useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{coursesApi}from'../../api';import PageState from'../../components/PageState.vue';import StatusTag from'../../components/StatusTag.vue';import CourseDialog from'./CourseDialog.vue';const router=useRouter(),items=ref([]),loading=ref(false),error=ref(''),total=ref(0),page=ref(1),pageSize=12,filters=reactive({keyword:'',status:''}),dialog=ref(false),editing=ref(null);const load=async()=>{loading.value=true;error.value='';try{const d=await coursesApi.list({...filters,page:page.value,page_size:pageSize});items.value=d.items;total.value=d.total}catch(e){error.value=e.message}finally{loading.value=false}};const edit=c=>{editing.value=c;dialog.value=true};const remove=async c=>{await ElMessageBox.confirm(`删除“${c.name}”后课程会被软删除，关联文件将停用。是否继续？`,'删除课程',{type:'warning',confirmButtonText:'确认删除'});await coursesApi.remove(c.id);ElMessage.success('课程已删除');load()};onMounted(load)</script>
<style scoped>.course-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:20px}.course-card{overflow:hidden}.cover{height:132px;background:linear-gradient(140deg,#e9f4ff,#ecfaf8);display:grid;place-items:center;color:var(--primary)}.cover svg{width:52px}.cover img{width:100%;height:100%;object-fit:cover}.course-content{padding:18px}.course-head{display:flex;justify-content:space-between;gap:10px;align-items:center}.course-head h3{margin:0;font-size:17px}.course-content p{height:44px;color:var(--text-secondary);overflow:hidden}.stats{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--text-secondary);padding:12px 0;border-top:1px solid var(--border)}.stats b{color:var(--text)}.actions{display:flex;margin-top:8px}@media(max-width:1500px){.course-grid{grid-template-columns:repeat(2,1fr)}}</style>
